sp_widget.client_script:
api.controller=function($scope) {
  /* widget controller */
  var c = this;
	// Estado inicial (pode ser null, true ou false)
$scope.isLowercase = null;

// Escuta evento do rootScope para atualizar o estado
$scope.$root.$on('toggleCaseEvent', function(event, isLowercase) {
  $scope.isLowercase = isLowercase;
});

};

sp_widget.css:
.servicos-widget {
  font-family: 'Roboto Flex', sans-serif !important;
  font-weight: 400;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%; /* Faz o container ocupar toda a largura */
  padding: 0 20px; /* Espaçamento interno opcional */
  box-sizing: border-box;
}

.blue-bar {
  width: 5px;
  height: 24px;
  background-color:  #ffa500;
  margin-right: 10px;
}

.fa.fa-map-marker{
	margin-left: 10px;
  color: #6CB4EE;
  font-size: 15px;
}

.servicos-text {
  font-size: 15px;
  color: black;
  padding: 10px;

}

.servicos-line {
  flex-grow: 1;
  height: 1px;
  background-color:  black;
  font-weight: bold;
}

.lowercase-text {
  text-transform: lowercase;
}

.uppercase-text {
  text-transform: uppercase;
}
